ALTER TABLE "categories" ADD COLUMN "description" text DEFAULT '' NOT NULL;--> statement-breakpoint
-- Starter text for the categories that already exist, so their pages are not all the same sentence on day one. Only fills an empty description; an admin can change any of them.
UPDATE "categories" SET "description" = 'Handmade crochet and textile pieces from independent makers across India: soft toys, wearables, home linen and more, worked stitch by stitch or woven and printed by hand. Each piece is made in small batches, so no two are exactly alike. Contact the maker directly to order or ask for a custom colour.' WHERE "slug" = 'crochet-and-textiles' AND "description" = '';--> statement-breakpoint
UPDATE "categories" SET "description" = 'Handmade accessories from independent Indian makers: bags, pouches, hair accessories and small everyday pieces in fabric, leather and thread. Made by hand in small batches, with the maker named on every listing. Contact them directly to order.' WHERE "slug" = 'accessories' AND "description" = '';--> statement-breakpoint
UPDATE "categories" SET "description" = 'Resin art by independent Indian makers: coasters, trays, keepsakes and jewellery, poured and cured by hand with pressed flowers, pigments and gold leaf. Every piece sets differently, so each one is one of a kind. Contact the maker directly to order or to commission your own.' WHERE "slug" = 'resin-art' AND "description" = '';--> statement-breakpoint
UPDATE "categories" SET "description" = 'Handmade pottery from independent Indian potters: cups, bowls, planters and decorative pieces, shaped on the wheel or by hand and glazed and fired in small batches. Glazes and shapes vary from piece to piece. Contact the potter directly to order.' WHERE "slug" = 'pottery' AND "description" = '';--> statement-breakpoint
UPDATE "categories" SET "description" = 'Original paintings and prints by independent Indian artists, from traditional miniature and folk styles to contemporary work on canvas and paper. Each painting is made by the artist named on the listing. Contact them directly to buy or to ask about a commission.' WHERE "slug" = 'paintings' AND "description" = '';
